                        q = p + step
                        while 0 < q < h - 1:
                            out[q][si] = obj
                            q += step

                # Project the active line to the matching opposite edge.
                if horizontal_lines:
                    for c in range(w):
                        if grid[ti][c] != edge:
                            out[ti][c] = obj
                else:
                    for r in range(h):
                        if grid[r][ti] != edge:
                            out[r][ti] = obj

    left = runs([grid[r][0] for r in range(h)])
    right = runs([grid[r][w - 1] for r in range(h)])
    for a in left:
        for b in right:
            if a[1] - a[0] == b[1] - b[0]:
                process(a, b, True)

    top = runs(grid[0])
    bottom = runs(grid[h - 1])
    for a in top:
        for b in bottom:
            if a[1] - a[0] == b[1] - b[0]:
                process(a, b, False)

    return out
